import React from 'react';
import { useNavigate } from 'react-router-dom';
import Icon from '../../components/AppIcon';
import { useAuth } from '../../contexts/AuthContext';
import { useMockData } from '../../contexts/MockDataContext';

export default function ResponderView() {
  const navigate = useNavigate();
  const { profile, signOut } = useAuth();
  const { reports: allReports, setReports } = useMockData();
  const reports = allReports.filter(r => r.assigned_to === profile?.id || r.status === 'pending').slice(0, 3);
  const update = (id, status) => setReports(items => items.map(item => item.report_id === id ? {...item, status} : item));
  return <div className="min-h-screen bg-slate-50"><header className="border-b border-slate-200 bg-white"><div className="mx-auto flex max-w-6xl items-center justify-between px-5 py-4"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-blue-700 text-white"><Icon name="Ambulance" size={21}/></div><div><p className="font-bold">Responder workspace</p><p className="text-xs text-slate-500">{profile?.department?.name || 'Admin-assigned department'} · On duty</p></div></div><div className="flex gap-2"><button onClick={() => navigate('/report-management')} className="rounded-xl border border-slate-200 px-3 py-2 text-sm font-semibold">Incident queue</button><button onClick={signOut} className="rounded-xl p-2 text-slate-500 hover:bg-slate-100"><Icon name="LogOut" size={19}/></button></div></div></header><main className="mx-auto max-w-6xl px-5 py-8"><div className="mb-6 flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-wider text-blue-700">Live assignments</p><h1 className="mt-1 text-3xl font-bold tracking-tight">Response board</h1><p className="mt-2 text-sm text-slate-500">Acknowledge and update your department's incidents. Dispatch receives every status update.</p></div><div className="rounded-xl bg-emerald-50 px-3 py-2 text-sm font-medium text-emerald-700"><span className="mr-2 inline-block h-2 w-2 animate-pulse rounded-full bg-emerald-500"/>Available for dispatch</div></div><div className="grid gap-5 lg:grid-cols-3">{reports.map((report, index) => <article key={report.report_id} className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-start justify-between gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-red-50 text-red-600"><Icon name={report.emergency_type === 'medical' ? 'HeartPulse' : 'Siren'} size={20}/></div><span className="rounded-full bg-red-50 px-2 py-1 text-[10px] font-bold uppercase text-red-700">{report.priority}</span></div><h2 className="mt-5 font-bold capitalize">{report.emergency_type} · {report.report_id}</h2><p className="mt-2 text-sm leading-6 text-slate-500">{report.description}</p><p className="mt-4 flex items-start gap-1 text-sm font-medium text-slate-700"><Icon name="MapPin" size={16} className="mt-0.5 text-blue-600"/>{report.location}</p><a className="mt-3 inline-flex items-center gap-1 text-sm font-semibold text-blue-700" href={`https://maps.google.com/?q=${report.latitude || ''},${report.longitude || ''}`} target="_blank" rel="noreferrer">Open navigation <Icon name="ArrowUpRight" size={15}/></a><div className="mt-5 border-t border-slate-100 pt-4"><p className="mb-3 text-xs font-bold uppercase tracking-wider text-slate-400">Current: {report.status?.replace('-', ' ')}</p><div className="flex flex-wrap gap-2">{['acknowledged','in-progress','resolved'].map(status => <button key={status} onClick={() => update(report.report_id, status)} className={`rounded-lg px-3 py-2 text-xs font-semibold ${report.status === status ? 'bg-blue-700 text-white' : 'bg-slate-100 text-slate-700 hover:bg-slate-200'}`}>{status === 'in-progress' ? 'En route / on scene' : status}</button>)}</div>{index === 0 && <button onClick={() => alert('A decline reason would be sent to the dispatcher and recorded in the incident timeline.')} className="mt-3 text-xs font-semibold text-slate-500 underline">Unable to respond</button>}</div></article>)}</div></main></div>;
}
